add('aoluguya','fun','reindeer','驯鹿互动与拍照','有人非常喜欢，也有人被人流与商业化劝退；更适合有明确喂鹿兴趣的人。','按园区要求互动，是否加购拍照服务现场决定。','拥挤时互动质量下降，不能保证一人一鹿；不同季节体验差异大。','D2 喂鹿可与觉乐二选一；想看文化展陈可保留敖鲁古雅，完整游览时间另计。',r(I,'少人时喂鹿体验好，来源是冬季旅行。'),r(AH,'五一喂驯鹿的亲身体验积极。'),r(AI,'认可驯鹿旅拍体验。'),r(J,'对票务服务和商业化失望。','negative'),r(S,'人多时需要等鹿，互动受影响。','mixed'),r('6a75ed6b0000000021020e5b','暑期人流大、动物疲惫，作者明确不建议专程前往。','negative'))

add('deerbur','fun','deer','兴安神鹿园 · 恢复开放待确认','截至 10 月 3 日的资料核查，9 月 26 日和 29 日有封路、当天闭园的亲访反馈，尚未核实恢复；暂不排入固定行程。','保留以往驯鹿、梅花鹿互动资料；确认恢复开放及接驳安排后再考虑。','旧亲访好评不等于当前开放。近期发布的回忆帖也不能证明恢复；不推断关闭原因。旧高德驾车增量只到登记停车点，不证明施工期间可通行。','D2 想喂鹿可优先比较根河出发端的觉乐与敖鲁古雅，确认恢复前不为神鹿园绕行。',r(T,'2025 年 9 月亲访认可梅花鹿与驯鹿互动，并提醒末段坑洼、信号差；只作历史体验。'),r('6ab7290d000000001b033dde','2026 年 9 月 26 日到访反馈道路封闭，步行也不让进入；不是 10 月 3 日营业结论。','negative'),r('6abb2b1b000000001c00d66e','2026 年 9 月 29 日到路口后被告知当天闭园，未能入园；尚无已核实恢复证据。','negative'))
add('deerbur','play','memorial','卡鲁奔 · 玛利亚索纪念馆线索','一篇途经笔记明确推荐小镇的纪念展示，可作为文化兴趣备选。','到店先询问是否对外开放及参观位置。','展示位于私人经营场所，当前开放、收费未核实；不把历史免费信息当承诺。','D2 路过小镇时短停，时间紧可略过。',r('6a6d464a0000000033030738','作者实到卡鲁奔，特别推荐其中的纪念馆。'))

add('mordaga','play','forest','森林公园与林间风景','园内可选红豆坡林间步道与一目九岭观景台，与小火车二选一安排。','红豆坡计划停留 30–45 分钟，一目九岭计划 45–60 分钟；两项为游玩估时，驾驶另看高德查验。','园内自驾通行及开放点位以入口当天确认为准；秋色进度每年不同，不能保证国庆仍有大片金叶。','D3 上午选园内两站或小火车，下午前往白鹿岛；不把两套完整玩法全叠加。',r(AE,'对森林公园秋景整体认可。'),r(AI,'实走根白线和森林公园，提醒九月下旬已有白桦落叶。'),r('6ab928f0000000000a020cd0','秋季自驾笔记认可红豆坡落叶松步道和一目九岭林海观景，提醒猎人之路需折返停车场。'))
add('mordaga','fun','train','森林小火车','适合喜欢慢行看林海的人，样本评价明显分裂；近期作者每站都下车共用约 4 小时。','一般规划预留 3 小时，优先第一站登高、第三站溪畔；每站都下需按约 4 小时安排。实际班次与候车时间到站确认。','负面反馈集中在排队、挤车与景色重复；3 小时是计划预留，并非保证完成时长。游览只走开放站点与步道，不在轨道拍照。','D3 与红豆坡＋一目九岭自驾两站择一；留足白鹿岛车程和下午活动时间。',r(AE,'追秋行程把小火车评为很喜欢的体验。'),r(AI,'实际乘坐，认可慢速行驶与窗边拍摄。'),r(AD,'实乘后对排队、拥挤和重复景色评价低。','negative'),r('6ab78d3600000000140390ab','亲历记录候车约半小时、每站都下共 4 小时，特别喜欢第一站高处林海，第三站可到水边。'))
add('mordaga','fun','market','镇上早市与林业历史短逛','偏生活化的体验，比专门打卡更适合顺路慢走。','看当季菌子野果，沿公开街道了解林业小镇。','不进入铁路、废弃场站或围栏内；私人住处做的包子不是对外餐厅。','D3 出发前有空再逛。',r(R,'亲访早市与林业小镇，描写山货和铁路历史。'))

add('bailudao','eat','restaurant','白鹿岛酒店中餐厅','10 月 4 日补读多篇近期用餐记录：热菜有好评，也有口味和价格分歧，适合到白鹿岛后先看菜单再决定。','近期作者认可菌菇汤、土豆南瓜和豆角排骨；另一篇喜欢鱼香肉丝。按当天菜单点，说明希望少盐。','有同餐同行者觉得不好吃、作者认为酸菜白肉肉量少；另有价格偏高反馈。四人两热一凉 231 元仅为一次消费记录，不是现价。今日营业、接待外客与供餐时间仍需确认；高德未核到餐厅独立 POI。','10 月 4 日下午到岛先确认漂流和餐厅晚餐时段，再安排晚餐；若上午提前抵达可询问午餐，不能把未确认营业当成保证。',r(AC,'2025 年 9 月实际用餐，认可干净热菜和蘑菇香味；为历史体验。'),r('6ac030d3000000001402de3a','10 月 3 日发布实吃记录，认可菌菇汤、土豆南瓜和豆角排骨，希望盐味再轻一点。'),r('6abe52db0000000018039699','作者喜欢酸菜白肉与鱼香肉丝，但同行者觉得不好吃，并认为白肉量偏少；同一篇按口味分歧处理。','mixed'),r('6abe55060000000012035ff0','近期到店记录四人两热一凉消费 231 元、份量适中；未评价味道，价格只作当次信息。','mention'),r('6abdf4b9000000001b02dbb5','近期提醒酒店餐厅价格偏高、周边补给有限；未给明确实吃菜品，不计口味推荐票。','mention'))
